      "output": "```js\n// 琴键疾跑 · 音乐与谱面（WebAudio 实时合成，不加载音频文件；顶层只定义函数并计算静态谱面）\nlet ctx = null, t0 = 0, nextBeat = 0, timer = null, noiseBuf = null;\nconst BPM = 120, SPB = 60 / BPM, BEATS = 90, LOOKAHEAD = 0.12, TICK_MS = 25;\nconst MEL = [0, 4, 7, 12, 11, 7, 4, 7, 9, 5, 9, 12, 7, 4, 2, -1]; // 相对 C4 的半音，16 拍循环\n// 谱面：仅 k=8…86 的偶数拍，固定种子混排缺口/横梁，偶尔留空；相邻障碍至少隔 2 拍（1 s）\nconst chart = (() => { let s = 7, last = -99; const out = [], rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;\n  for (let k = 8; k <= 86; k += 2) { if (k - last < 2 || rnd() < 0.2) continue;\n    out.push({ beat: k, time: k * SPB, type: rnd() < 0.55 ? 'gap' : 'beam' }); last = k; }\n  return out; })();\nfunction env(node, t, peak, dur) { const g = ctx.createGain(); g.gain.setValueAtTime(peak, t);\n  g.gain.exponentialRampToValueAtTime(0.001, t + dur); node.connect(g).connect(ctx.destination); }\nfunction tone(type, f0, f1, t, peak, dur) { const o = ctx.createOscillator(); o.type = type; o.frequency.setValueAtTime(f0, t);\n  o.frequency.exponentialRampToValueAtTime(f1, t + dur); env(o, t, peak, dur); o.start(t); o.stop(t + dur + 0.02); }\nfunction noise(t, dur, hp, peak) { const src = ctx.createBufferSource(), f = ctx.createBiquadFilter(); src.buffer = noiseBuf;\n  f.type = 'highpass'; f.frequency.value = hp; src.connect(f); env(f, t, peak, dur); src.start(t); src.stop(t + dur + 0.02); }\nconst kick = t => tone('sine', 150, 40, t, 0.9, 0.3);\nconst snare = t => { noise(t, 0.18, 1000, 0.5); tone('triangle', 180, 120, t, 0.3, 0.1); };\nconst hat = t => noise(t, 0.05, 7000, 0.18);\nconst piano = (t, n) => { const f = 261.63 * Math.pow(2, n / 12); tone('triangle', f, f, t, 0.22, 0.9); tone('sine', f * 2, f * 2, t, 0.08, 0.5); };\nfunction schedule() { // 前瞻调度：把落在 [now, now+LOOKAHEAD) 内的拍子按 AudioContext 时间轴精确排进去\n  while (nextBeat < BEATS && t0 + nextBeat * SPB < ctx.currentTime + LOOKAHEAD) {\n    const t = t0 + nextBeat * SPB, b = nextBeat % 4;\n    if (b === 0 || b === 2) kick(t); else snare(t);\n    hat(t); hat(t + SPB / 2); piano(t, MEL[nextBeat % 16]); nextBeat++; }\n  if (nextBeat >= BEATS) { clearInterval(timer); timer = null; } }\nfunction startMusic() { // 须在用户操作（点击/按键）的事件处理里调用；重来时再次调用即可取新 t0\n  if (!ctx) { ctx = new (window.AudioContext || window.webkitAudioContext)();\n    noiseBuf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate); const d = noiseBuf.getChannelData(0);\n    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; }\n  if (ctx.state === 'suspended') ctx.resume();\n  clearInterval(timer); t0 = ctx.currentTime + 0.1; nextBeat = 0; schedule(); timer = setInterval(schedule, TICK_MS); return t0; }\nfunction songTime() { return ctx ? Math.max(0, ctx.currentTime - t0) : 0; }\nwindow.Music = { startMusic, songTime, chart, SPB, BEATS };\n```\n\n**说明**\n- **主时钟**：所有发声时刻都是 `t0 + k × 0.5`，基于 `AudioContext.currentTime`。`setInterval` 只用来每 25 ms 唤醒调度器，不参与计时。`songTime()` 在开始前返回 0，开始后返回 `max(0, currentTime − t0)`。t0 比调用时刻晚 0.1 s，这样第一拍也能被提前排进时间轴。\n- **谱面**：`chart` 中每项为 `{beat, time, type: 'gap'|'beam'}`。障碍只放在第 8–86 拍的偶数拍上，前 8 拍留空热身。相邻障碍至少隔 2 拍（1 s），约 20% 的偶数拍留空。种子固定，所以每次生成的谱面相同。\n- **顶层行为**：只定义函数和常量，并纯计算出 `chart`。顶层不创建 AudioContext，也不启动定时器。`chart` 可通过全局变量或 `window.Music` 取用。\n\n**未验证项**（本节点未实际在浏览器中运行）\n- 未实际试听，鼓组与钢琴的音色和音量未经调校。\n- 未在浏览器控制台中检查 `chart` 的实际内容。\n- 重来时，上一局已提前排好的约 0.12 s 内的音符仍会响完，未做静音处理。\n- 若浏览器在调用后 AudioContext 仍处于挂起状态，`currentTime` 会停住，`songTime()` 也随之停住。未在 iOS Safari 上验证。"
